// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(address caller, bool prankAsOwner) public {
        vm.assume(caller != address(this));
        bool ok;
        if (prankAsOwner) {
            vm.prank(address(this));
        } else {
            vm.prank(caller);
        }
        try c.OpenToThePublic() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!prankAsOwner ? !ok : ok);
    }
}
